', direction=None, fact=None, file_name='/workspace/sandbox/variants/accessible_minimal/modal-dialog--framework-react--style-modern/google/gemini-3-flash-preview__s1/app.js', full_command_text=None, hook_message=None, intention='Edit file', new_file_contents='const { useState, useEffect, useRef } = React;

const Modal = ({ isOpen, onClose, title, description, onConfirm }) => {
  const modalRef = useRef(null);
  const previousFocus = useRef(null);

  useEffect(() => {
    if (isOpen) {
      previousFocus.current = document.activeElement;
      // Simple focus trap: find all focusable elements
      const focusableElements = modalRef.current.querySelectorAll(
        'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
      );
      if (focusableElements.length > 0) {
        focusableElements[0].focus();
      }

      const handleKeyDown = (e) => {
        if (e.key === 'Escape') onClose();
        if (e.key === 'Tab') {
          const first = focusableElements[0];
          const last = focusableElements[focusableElements.length - 1];

          if (e.shiftKey && document.activeElement === first) {
            last.focus();
            e.preventDefault();
          } else if (!e.shiftKey && document.activeElement === last) {
            first.focus();
            e.preventDefault();
          }
        }
      };

      document.addEventListener('keydown', handleKeyDown);
      return () => document.removeEventListener('keydown', handleKeyDown);
    } else if (previousFocus.current) {
      previousFocus.current.focus();
    }
  }, [isOpen, onClose]);

  return (
    <div 
      className={`modal-overlay ${isOpen ? 'open' : ''}`}
      onClick={(e) => e.target === e.currentTarget && onClose()}
      aria-hidden={!isOpen}
    >
      <div 
        className="modal-content"
        ref={modalRef}
        role="dialog"
        aria-modal="true"
        aria-labelledby="modal-title"
        aria-describedby="modal-description"
        tabIndex="-1"
      >
        <h2 id="modal-title" className="modal-title">{title}</h2>
        <p id="modal-description" className="modal-description">{description}</p>
        <div className="modal-actions">
          <button className="btn btn-secondary" onClick={onClose}>
            Cancel
          </button>
          <button className="btn btn-danger" onClick={onConfirm}>
            Delete Image
          </button>
        </div>
      </div>
    </div>
  );
};

const App = () => {
  const [isModalOpen, setIsModalOpen] = useState(false);

  const handleDelete = () => {
    // Logic to delete image
    console.log("Image deleted");
    setIsModalOpen(false);
  };

  return (
    <div className="container">
      <img 
        src="https://images.unsplash.com/photo-1506744038136-46273834b3fb?auto=format&fit=crop&w=800&q=80" 
        alt="Mountain landscape" 
        className="image-preview"
      />
      <div className="content">
        <h1 style={{ fontSize: '1.5rem', marginBottom: '8px' }}>Mountain Landscape</h1>
        <p style={{ color: '#6b7280', marginBottom: '20px' }}>Added on May 6, 2026</p>
        <button 
          className="trigger" 
          onClick={() => setIsModalOpen(true)}
          aria-haspopup="dialog"
        >
          Delete Image
        </button>
      </div>

      <Modal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onConfirm={handleDelete}
        title="Delete Image?"
        description="Are you sure you want to delete this image? This action cannot be undone and the image will be permanently removed from your library."
      />
    </div>
  );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<App />);
